export default {

  "catalog": {
    "objects": [
      {"name":"Product2","type":"standard","domain":"catalog","description":"Product2 represents an item or service defined in the Revenue Cloud product catalog. Name, ProductCode, Description, Family, StockKeepingUnit, and QuantityUnitOfMeasure identify and describe the offering, while IsActive controls whether it is available for use.","fields":[{"name":"Name","type":"Text","description":"Display name shown to sales reps and customers"},{"name":"ProductCode","type":"Text","description":"Unique code that identifies this product across systems"},{"name":"Description","type":"TextArea","description":"Detailed description of the product for internal and external use"},{"name":"IsActive","type":"Boolean","description":"Controls whether the product can be added to new quotes and orders"},{"name":"Family","type":"Picklist","description":"Logical grouping such as hardware, software, or services"},{"name":"QuantityUnitOfMeasure","type":"Picklist","description":"Unit used when measuring quantity, such as each, license, or hour"},{"name":"StockKeepingUnit","type":"Text","description":"Inventory tracking identifier used by warehouse or fulfillment systems"}],"relationships":[{"target":"PricebookEntry","type":"parent","description":"Products are listed in price books through price book entry records"},{"target":"ProductCategory","type":"lookup","description":"Products can be assigned to categories within a product catalog"}]},
      {"name":"ProductCatalog","type":"standard","domain":"catalog","description":"ProductCatalog represents a collection of products organized for browsing and sale. Name and Description identify the catalog, IsActive indicates whether it is available, and ExternalReference can associate it with an external source.","fields":[{"name":"Name","type":"Text","description":"Display name for this catalog"},{"name":"Description","type":"TextArea","description":"Purpose or scope of this catalog"},{"name":"IsActive","type":"Boolean","description":"Whether this catalog is available for use"},{"name":"ExternalReference","type":"Text","description":"Identifier used to link this catalog to external commerce systems"}],"relationships":[{"target":"ProductCategory","type":"parent","description":"A catalog contains one or more product categories"}]},
      {"name":"ProductCategory","type":"standard","domain":"catalog","description":"ProductCategory represents a hierarchical grouping of products within a catalog. CatalogId associates the category with its catalog, ParentCategoryId establishes a subcategory relationship, and SortOrder controls its browsing sequence alongside Name and Description.","fields":[{"name":"Name","type":"Text","description":"Category label shown in the catalog hierarchy"},{"name":"Description","type":"TextArea","description":"Explanation of what this category contains"},{"name":"CatalogId","type":"Lookup","description":"The catalog this category belongs to"},{"name":"ParentCategoryId","type":"Lookup","description":"Parent category for building nested hierarchies"},{"name":"SortOrder","type":"Number","description":"Display order within the parent category or catalog"}],"relationships":[{"target":"ProductCatalog","type":"child","description":"Each category belongs to a single catalog"},{"target":"Product2","type":"parent","description":"Categories contain products assigned to them"}]},
      {"name":"ProductAttribute","type":"standard","domain":"catalog","description":"ProductAttribute represents a characteristic assigned to a product definition. Name and DataType define the attribute, DefaultValue supplies its initial value, Sequence controls its run-time order, and ProductAttributeSetId associates it with an attribute set.","fields":[{"name":"Name","type":"Text","description":"Human-readable name for this attribute"},{"name":"DataType","type":"Picklist","description":"The data type of attribute values, such as text, number, or picklist"},{"name":"DefaultValue","type":"Text","description":"Pre-selected value when no explicit choice is made"},{"name":"Sequence","type":"Number","description":"Display order of this attribute within its attribute set"},{"name":"ProductAttributeSetId","type":"Lookup","description":"The attribute set this attribute belongs to"}],"relationships":[{"target":"ProductAttributeSet","type":"child","description":"Each attribute belongs to an attribute set"},{"target":"Product2","type":"lookup","description":"Attributes are associated with the products they describe"}]},
      {"name":"ProductAttributeSet","type":"standard","domain":"catalog","description":"ProductAttributeSet represents a named, reusable grouping of product attributes. DeveloperName and MasterLabel identify the set for configuration and display, while Description documents its intended use.","fields":[{"name":"DeveloperName","type":"Text","description":"Unique API name used to reference this attribute set in configuration rules"},{"name":"MasterLabel","type":"Text","description":"Display label for this attribute set"},{"name":"Description","type":"TextArea","description":"Explanation of when and how to use this attribute set"}],"relationships":[{"target":"ProductAttribute","type":"parent","description":"An attribute set contains one or more attributes"},{"target":"Product2","type":"lookup","description":"Attribute sets are assigned to the products they configure"}]},
      {"name":"ProductRelatedComponent","type":"standard","domain":"catalog","description":"ProductRelatedComponent represents a parent-child product relationship within a bundle. ParentProductId and ChildProductId identify the connected products, while Quantity, IsOptional, and IsQuantityEditable define the component's default quantity and run-time selection behavior.","fields":[{"name":"Name","type":"Text","description":"Display name for this component within the bundle"},{"name":"ParentProductId","type":"Lookup","description":"The parent bundle product that contains this component"},{"name":"ChildProductId","type":"Lookup","description":"The product that serves as a component of the bundle"},{"name":"Quantity","type":"Number","description":"Default quantity of this component included in the bundle"},{"name":"IsOptional","type":"Boolean","description":"Whether the buyer can choose to include or exclude this component"},{"name":"IsQuantityEditable","type":"Boolean","description":"Whether the buyer can change the default quantity"}],"relationships":[{"target":"Product2","type":"child","description":"Links to the parent bundle product"},{"target":"ProductComponentGroup","type":"child","description":"Components are organized into groups within the bundle"}]},
      {"name":"ProductComponentGroup","type":"standard","domain":"catalog","description":"ProductComponentGroup represents a logical group of related components in a bundled product. ProductId associates the group with its product, MinQuantity and MaxQuantity define group cardinality, and Sequence controls the group's display order.","fields":[{"name":"Name","type":"Text","description":"Group label displayed during product configuration"},{"name":"ProductId","type":"Lookup","description":"The bundle product this group belongs to"},{"name":"MinQuantity","type":"Number","description":"Minimum number of selections a buyer must make from this group"},{"name":"MaxQuantity","type":"Number","description":"Maximum number of selections allowed from this group"},{"name":"Sequence","type":"Number","description":"Display order of this group within the bundle configuration"}],"relationships":[{"target":"Product2","type":"child","description":"Each group belongs to one bundle product"},{"target":"ProductRelatedComponent","type":"parent","description":"A group contains one or more component options"}]}
    ]
  },

  "pricing": {
    "objects": [
      {"name":"Pricebook2","type":"standard","domain":"pricing","description":"Pricebook2 represents a centralized list of product selling prices in Revenue Cloud. Name and Description identify the price book, while IsActive and IsStandard indicate whether it is active and whether it is the standard price book.","fields":[{"name":"Name","type":"Text","description":"Display name for this price book"},{"name":"Description","type":"TextArea","description":"Explanation of when to use this price book, such as region or channel"},{"name":"IsActive","type":"Boolean","description":"Whether this price book can be assigned to new transactions"},{"name":"IsStandard","type":"Boolean","description":"System flag indicating this is the organization's default price book"}],"relationships":[{"target":"PricebookEntry","type":"parent","description":"A price book contains price entries for each product it lists"},{"target":"Quote","type":"parent","description":"Quotes reference a price book for line item pricing"},{"target":"Order","type":"parent","description":"Orders reference a price book for their line item pricing"}]},
      {"name":"PricebookEntry","type":"standard","domain":"pricing","description":"PricebookEntry associates a product with a price book through Product2Id and Pricebook2Id and records its UnitPrice and CurrencyIsoCode. UseStandardPrice and IsActive indicate whether the entry uses the standard price and whether the entry is active.","fields":[{"name":"UnitPrice","type":"Currency","description":"The price per unit for this product in this price book"},{"name":"UseStandardPrice","type":"Boolean","description":"If true, this entry inherits the price from the standard price book"},{"name":"IsActive","type":"Boolean","description":"Whether this price entry is available for use on new line items"},{"name":"Product2Id","type":"Lookup","description":"The product this price entry is for"},{"name":"Pricebook2Id","type":"Lookup","description":"The price book this entry belongs to"},{"name":"CurrencyIsoCode","type":"Text","description":"ISO currency code when multi-currency is enabled"}],"relationships":[{"target":"Product2","type":"child","description":"Each entry represents one product's price"},{"target":"Pricebook2","type":"child","description":"Each entry belongs to one price book"}]},
      {"name":"PriceAdjustmentSchedule","type":"standard","domain":"pricing","description":"PriceAdjustmentSchedule represents a grouped set of product price adjustments. Name and Description identify the schedule, while AdjustmentType and AdjustmentMethod define the adjustment, and PriceAdjustmentScheduleId identifies the schedule record.","fields":[{"name":"Name","type":"Text","description":"Descriptive name for this adjustment schedule"},{"name":"Description","type":"TextArea","description":"Explanation of the pricing strategy this schedule implements"},{"name":"AdjustmentType","type":"Picklist","description":"Whether the adjustment is a discount, surcharge, or override"},{"name":"AdjustmentMethod","type":"Picklist","description":"Whether the adjustment is a percentage or a fixed amount"},{"name":"PriceAdjustmentScheduleId","type":"Lookup","description":"Self-reference for chaining multiple adjustment schedules"}],"relationships":[{"target":"PriceAdjustmentTier","type":"parent","description":"A schedule contains one or more tiers defining the adjustment at each level"},{"target":"Product2","type":"lookup","description":"Schedules can be attached to specific products"}]},
      {"name":"PriceAdjustmentTier","type":"standard","domain":"pricing","description":"PriceAdjustmentTier defines an ordered adjustment tier associated with a PriceAdjustmentSchedule through PriceAdjustmentScheduleId. LowerBound, UpperBound, AdjustmentValue, TierType, and Sequence describe the tier's range, adjustment, type, and execution order.","fields":[{"name":"LowerBound","type":"Number","description":"Minimum quantity or value threshold where this tier begins"},{"name":"UpperBound","type":"Number","description":"Maximum quantity or value threshold where this tier ends"},{"name":"AdjustmentValue","type":"Number","description":"The discount or surcharge amount applied at this tier"},{"name":"TierType","type":"Picklist","description":"Whether this tier is based on quantity, revenue, or another metric"},{"name":"PriceAdjustmentScheduleId","type":"Lookup","description":"The schedule this tier belongs to"},{"name":"Sequence","type":"Number","description":"Evaluation order of this tier within the schedule"}],"relationships":[{"target":"PriceAdjustmentSchedule","type":"child","description":"Each tier belongs to one adjustment schedule"}]}
    ]
  },

  "rates": {
    "objects": [
      {"name":"RateCard","type":"standard","domain":"rates","description":"RateCard represents a rate card used to define consumption-based rates for usage resources. Name and Description identify the card, Status controls its lifecycle state, and EffectiveDate and ExpirationDate define the period during which it applies.","fields":[{"name":"Name","type":"Text","description":"Descriptive name for this rate card"},{"name":"Description","type":"TextArea","description":"Explanation of the pricing scenario this rate card addresses"},{"name":"Status","type":"Picklist","description":"Whether this rate card is draft, active, or retired"},{"name":"EffectiveDate","type":"Date","description":"Date from which this rate card's prices are applicable"},{"name":"ExpirationDate","type":"Date","description":"Date after which this rate card is no longer valid"}],"relationships":[{"target":"Product2","type":"lookup","description":"Rate cards can be associated with specific products"},{"target":"PricebookEntry","type":"lookup","description":"Rate card values can override standard price book pricing"}]},
      {"name":"RatingProcedure","type":"standard","domain":"rates","description":"RatingProcedure represents an ordered rating process that calculates the final net rate of a usage resource. Name and Description identify the procedure, Status indicates its lifecycle state, and ProcessingOrder records its execution ordering information.","fields":[{"name":"Name","type":"Text","description":"Name identifying this rating procedure"},{"name":"Description","type":"TextArea","description":"Explanation of the pricing calculation this procedure performs"},{"name":"Status","type":"Picklist","description":"Current lifecycle state of this procedure"},{"name":"ProcessingOrder","type":"Number","description":"Sequence in which this procedure runs relative to others"}],"relationships":[{"target":"RateCard","type":"lookup","description":"Rating procedures reference rate cards for price lookups"}]}
    ]
  },

  "configurator": {
    "objects": [
      {"name":"ProductConfigurationRule","type":"standard","domain":"configurator","description":"ProductConfigurationRule represents a configuration rule that applies product or attribute conditions and produces a configuration action or validation outcome. Its fields identify the rule through Name and RuleType, associate SourceProductId and TargetProductId, indicate availability through IsActive, and store an ErrorMessage for the applicable rule outcome.","fields":[{"name":"Name","type":"Text","description":"Descriptive name explaining what this rule enforces"},{"name":"RuleType","type":"Picklist","description":"The type of constraint, such as inclusion, exclusion, or validation"},{"name":"SourceProductId","type":"Lookup","description":"The product selection that triggers this rule"},{"name":"TargetProductId","type":"Lookup","description":"The product affected by this rule"},{"name":"IsActive","type":"Boolean","description":"Whether this rule is currently enforced"},{"name":"ErrorMessage","type":"TextArea","description":"Message shown when a configuration violates this rule"}],"relationships":[{"target":"Product2","type":"lookup","description":"Rules reference source and target products"},{"target":"ProductComponentGroup","type":"lookup","description":"Rules can apply to specific component groups within a bundle"}]},
      {"name":"ProductBundle","type":"standard","domain":"configurator","description":"ProductBundle represents a bundled offering associated with a catalog product and identifies whether the bundle can be configured during sale. Name, ProductId, BundleType, IsConfigurable, and Status capture the bundle's identity, product association, behavior, and lifecycle state.","fields":[{"name":"Name","type":"Text","description":"Display name for this bundle offering"},{"name":"ProductId","type":"Lookup","description":"The parent product record this bundle represents"},{"name":"BundleType","type":"Picklist","description":"Whether this is a static bundle, dynamic bundle, or kit"},{"name":"IsConfigurable","type":"Boolean","description":"Whether buyers can modify component selections"},{"name":"Status","type":"Picklist","description":"Lifecycle state of this bundle definition"}],"relationships":[{"target":"Product2","type":"child","description":"Each bundle is based on a parent product record"},{"target":"ProductRelatedComponent","type":"parent","description":"Bundles contain components that make up the offering"},{"target":"ProductComponentGroup","type":"parent","description":"Bundle components are organized into selectable groups"}]},
      {"name":"ConfigurationAttribute","type":"standard","domain":"configurator","description":"ConfigurationAttribute records a configured product attribute value and associates it with a catalog product or quote line item. AttributeName and AttributeValue store the selection, ProductId and QuoteLineItemId provide its product and transaction context, and Sequence controls its ordering.","fields":[{"name":"AttributeName","type":"Text","description":"Name of the attribute being configured"},{"name":"AttributeValue","type":"Text","description":"The value selected by the buyer for this attribute"},{"name":"ProductId","type":"Lookup","description":"The product being configured"},{"name":"QuoteLineItemId","type":"Lookup","description":"The quote line item this configuration applies to"},{"name":"Sequence","type":"Number","description":"Display order of this attribute in the configuration view"}],"relationships":[{"target":"Product2","type":"child","description":"Configuration attributes reference the product being configured"},{"target":"QuoteLineItem","type":"child","description":"Selected configurations are stored against quote line items"}]}
    ]
  },

  "transactions": {
    "objects": [
      {"name":"Quote","type":"standard","domain":"transactions","description":"Quote represents a preliminary customer offer containing products, services, and pricing before an order is finalized. Name, Status, ExpirationDate, GrandTotal, and TotalPrice describe the proposal and its calculated value, while AccountId, OpportunityId, and ContactId associate it with the relevant sales records.","fields":[{"name":"Name","type":"Text","description":"Name or number identifying this quote"},{"name":"Status","type":"Picklist","description":"Current stage such as draft, presented, or accepted"},{"name":"ExpirationDate","type":"Date","description":"Date after which this quote is no longer valid"},{"name":"GrandTotal","type":"Currency","description":"Total amount including all line items, taxes, and adjustments"},{"name":"TotalPrice","type":"Currency","description":"Sum of all line item prices before adjustments"},{"name":"AccountId","type":"Lookup","description":"The customer account this quote is for"},{"name":"OpportunityId","type":"Lookup","description":"The opportunity this quote is associated with"},{"name":"ContactId","type":"Lookup","description":"The primary contact at the customer for this quote"}],"relationships":[{"target":"QuoteLineItem","type":"parent","description":"A quote contains one or more line items detailing products and prices"},{"target":"Order","type":"parent","description":"An accepted quote can be converted into an order"},{"target":"Opportunity","type":"child","description":"Each quote is linked to an opportunity for pipeline tracking"}]},
      {"name":"QuoteLineItem","type":"standard","domain":"transactions","description":"QuoteLineItem represents a product line included in a quote and participates in configuration and pricing. Product2Id identifies the product; Quantity, UnitPrice, ListPrice, TotalPrice, and Discount capture the line's quantity and pricing values.","fields":[{"name":"Product2Id","type":"Lookup","description":"The product being quoted on this line"},{"name":"Quantity","type":"Number","description":"Number of units being quoted"},{"name":"UnitPrice","type":"Currency","description":"Price per unit after any adjustments"},{"name":"ListPrice","type":"Currency","description":"Original price per unit from the price book"},{"name":"TotalPrice","type":"Currency","description":"Extended price calculated as quantity times unit price"},{"name":"Discount","type":"Percent","description":"Percentage discount applied to this line item"}],"relationships":[{"target":"Quote","type":"child","description":"Each line item belongs to one quote"},{"target":"Product2","type":"lookup","description":"References the product being quoted"},{"target":"PricebookEntry","type":"lookup","description":"Price is derived from the price book entry"}]},
      {"name":"Order","type":"standard","domain":"transactions","description":"Order represents a formal customer transaction that can be created directly or converted from a quote. OrderNumber, Status, EffectiveDate, EndDate, and TotalAmount describe the order, while AccountId, ContractId, and Pricebook2Id connect it to its customer, contract, and price book.","fields":[{"name":"OrderNumber","type":"Text","description":"System-generated unique identifier for this order"},{"name":"Status","type":"Picklist","description":"Current state such as draft, activated, or completed"},{"name":"EffectiveDate","type":"Date","description":"Date when this order takes effect"},{"name":"EndDate","type":"Date","description":"Date when this order's term concludes"},{"name":"TotalAmount","type":"Currency","description":"Total monetary value of all order items"},{"name":"AccountId","type":"Lookup","description":"The customer account this order is placed for"},{"name":"ContractId","type":"Lookup","description":"The contract governing this order's terms"},{"name":"Pricebook2Id","type":"Lookup","description":"The price book used for pricing order items"}],"relationships":[{"target":"OrderItem","type":"parent","description":"An order contains one or more order items"},{"target":"FulfillmentOrder","type":"parent","description":"Orders are fulfilled through fulfillment order records"},{"target":"Contract","type":"child","description":"Orders can be governed by a master contract"},{"target":"Quote","type":"child","description":"Orders can originate from an accepted quote"}]},
      {"name":"OrderItem","type":"standard","domain":"transactions","description":"OrderItem represents a product or service included in an order and supplies transaction data for assetization, billing, and fulfillment. Product2Id, Quantity, UnitPrice, and TotalPrice capture the ordered product and price, while ServiceDate and EndDate define its service period.","fields":[{"name":"Product2Id","type":"Lookup","description":"The product being ordered"},{"name":"Quantity","type":"Number","description":"Number of units ordered"},{"name":"UnitPrice","type":"Currency","description":"Price per unit for this order line"},{"name":"TotalPrice","type":"Currency","description":"Extended price calculated as quantity times unit price"},{"name":"ServiceDate","type":"Date","description":"Date when service or delivery begins for this line item"},{"name":"EndDate","type":"Date","description":"Date when service or delivery ends for this line item"}],"relationships":[{"target":"Order","type":"child","description":"Each order item belongs to one order"},{"target":"Product2","type":"lookup","description":"References the product being purchased"},{"target":"BillingSchedule","type":"parent","description":"Order items can generate billing schedules for recurring charges"}]},
      {"name":"Contract","type":"standard","domain":"transactions","description":"Contract represents an agreement used to organize customer products, assets, and negotiated pricing throughout their lifecycle. ContractNumber, Status, StartDate, EndDate, and ContractTerm define the agreement, and AccountId associates it with the customer account.","fields":[{"name":"ContractNumber","type":"Text","description":"System-generated unique identifier for this contract"},{"name":"Status","type":"Picklist","description":"Current stage such as draft, activated, or expired"},{"name":"StartDate","type":"Date","description":"Date when the contract term begins"},{"name":"EndDate","type":"Date","description":"Date when the contract term expires"},{"name":"ContractTerm","type":"Number","description":"Duration of the contract in months"},{"name":"AccountId","type":"Lookup","description":"The customer account this contract is with"}],"relationships":[{"target":"Order","type":"parent","description":"A contract can govern multiple orders over its term"},{"target":"Account","type":"child","description":"Each contract belongs to a customer account"}]},
      {"name":"OpportunityLineItem","type":"standard","domain":"transactions","description":"OpportunityLineItem represents a product associated with an opportunity and can be synchronized from a quote line item. Product2Id, Quantity, UnitPrice, TotalPrice, ServiceDate, and Description capture the product, commercial value, service timing, and line details used in the opportunity.","fields":[{"name":"Product2Id","type":"Lookup","description":"The product associated with this opportunity line"},{"name":"Quantity","type":"Number","description":"Number of units the customer is interested in"},{"name":"UnitPrice","type":"Currency","description":"Proposed price per unit"},{"name":"TotalPrice","type":"Currency","description":"Extended price for this line item"},{"name":"ServiceDate","type":"Date","description":"Expected start date for this product or service"},{"name":"Description","type":"TextArea","description":"Notes about this line item"}],"relationships":[{"target":"Opportunity","type":"child","description":"Each line item belongs to one opportunity"},{"target":"Product2","type":"lookup","description":"References the product being proposed"},{"target":"PricebookEntry","type":"lookup","description":"Pricing comes from the opportunity's price book"}]}
    ]
  },

  "procedures": {
    "objects": [
      {"name":"ExpressionSet","type":"standard","domain":"procedures","description":"ExpressionSet represents reusable executable logic assembled from ordered elements and exposed through one or more versions. Its Name, Description, Status, ApiName, and UsageType fields identify the expression set, document its purpose, and indicate its lifecycle and intended use.","fields":[{"name":"Name","type":"Text","description":"Identifying name for this expression set"},{"name":"Description","type":"TextArea","description":"Explanation of the business logic this expression set implements"},{"name":"Status","type":"Picklist","description":"Whether this expression set is draft, active, or deprecated"},{"name":"ApiName","type":"Text","description":"Unique programmatic name used to invoke this expression set"},{"name":"UsageType","type":"Picklist","description":"Context where this expression set is used, such as pricing or qualification"}],"relationships":[{"target":"DecisionTable","type":"lookup","description":"Expression sets can reference decision tables for lookup-based logic"}]},
      {"name":"DecisionTable","type":"standard","domain":"procedures","description":"DecisionTable represents a lookup configuration that evaluates source data against defined input conditions and returns matching result fields. Its Name, Description, Status, CollectOperator, and SourceObject fields store the table's identity, lifecycle, matching configuration, and source of business rules.","fields":[{"name":"Name","type":"Text","description":"Identifying name for this decision table"},{"name":"Description","type":"TextArea","description":"Explanation of the business rules encoded in this table"},{"name":"Status","type":"Picklist","description":"Whether this table is draft, active, or retired"},{"name":"CollectOperator","type":"Picklist","description":"How multiple matching rows are resolved, such as first match or collect all"},{"name":"SourceObject","type":"Text","description":"The object whose data is evaluated against this table's conditions"}],"relationships":[{"target":"ExpressionSet","type":"lookup","description":"Decision tables can be called from expression sets"},{"target":"ContextDefinition","type":"lookup","description":"Decision tables use context definitions to access input data"}]},
      {"name":"ContextDefinition","type":"standard","domain":"procedures","description":"ContextDefinition represents a logical data model made up of nodes, attributes, tags, and mappings used by Context Service at run time. Its Name, Description, Status, and RootEntity fields identify the definition, describe its purpose, indicate its lifecycle, and specify its root logical entity.","fields":[{"name":"Name","type":"Text","description":"Identifying name for this context definition"},{"name":"Description","type":"TextArea","description":"Explanation of the data this context makes available"},{"name":"Status","type":"Picklist","description":"Whether this context definition is draft or active"},{"name":"RootEntity","type":"Text","description":"The primary object this context is built around"}],"relationships":[{"target":"DecisionTable","type":"parent","description":"Context definitions supply data to decision tables"},{"target":"ExpressionSet","type":"parent","description":"Context definitions supply data to expression sets"}]},
      {"name":"BatchProcessJob","type":"standard","domain":"procedures","description":"BatchProcessJob represents a monitored batch execution for asynchronous processing. Its Name, JobType, Status, TotalRecords, ProcessedRecords, and ScheduledDate fields identify the job, record its processing type and schedule, and track execution progress.","fields":[{"name":"Name","type":"Text","description":"Identifying name for this batch job"},{"name":"JobType","type":"Picklist","description":"The type of batch operation, such as billing, rating, or pricing"},{"name":"Status","type":"Picklist","description":"Current execution state such as queued, processing, completed, or failed"},{"name":"TotalRecords","type":"Number","description":"Total number of records to be processed"},{"name":"ProcessedRecords","type":"Number","description":"Number of records successfully processed so far"},{"name":"ScheduledDate","type":"DateTime","description":"When this batch job is scheduled to run"}],"relationships":[{"target":"ExpressionSet","type":"lookup","description":"Batch jobs can execute expression sets against each record"}]}
    ]
  },

  "approvals": {
    "objects": [
      {"name":"ProcessInstance","type":"standard","domain":"approvals","description":"ProcessInstance represents an approval process instance associated with the record identified by TargetObjectId. Status, SubmittedById, CompletedDate, and ProcessDefinitionId identify its current state, submitter, completion timing, and governing process definition.","fields":[{"name":"TargetObjectId","type":"Lookup","description":"The record being submitted for approval, such as a quote or order"},{"name":"Status","type":"Picklist","description":"Overall approval status: pending, approved, rejected, or recalled"},{"name":"SubmittedById","type":"Lookup","description":"The user who submitted the record for approval"},{"name":"CompletedDate","type":"DateTime","description":"When the approval process reached a final decision"},{"name":"ProcessDefinitionId","type":"Lookup","description":"The approval process definition being executed"}],"relationships":[{"target":"ProcessInstanceStep","type":"parent","description":"Each approval instance contains one or more approval steps"},{"target":"Quote","type":"lookup","description":"Approval processes are commonly applied to quotes requiring management review"},{"target":"Order","type":"lookup","description":"Orders above certain thresholds may require approval before activation"}]},
      {"name":"ProcessInstanceStep","type":"standard","domain":"approvals","description":"ProcessInstanceStep records an individual completed or historical step within an approval process. StepStatus, ActorId, OriginalActorId, Comments, and CreatedDate capture the step outcome, assigned and original actors, reviewer comments, and creation time.","fields":[{"name":"StepStatus","type":"Picklist","description":"Decision at this step: pending, approved, rejected, or reassigned"},{"name":"ActorId","type":"Lookup","description":"The user or queue assigned to make the decision at this step"},{"name":"OriginalActorId","type":"Lookup","description":"The originally assigned approver before any reassignment"},{"name":"Comments","type":"TextArea","description":"Comments provided by the approver explaining their decision"},{"name":"CreatedDate","type":"DateTime","description":"When this approval step was created"}],"relationships":[{"target":"ProcessInstance","type":"child","description":"Each step belongs to one approval process instance"}]},
      {"name":"ProcessInstanceWorkitem","type":"standard","domain":"approvals","description":"ProcessInstanceWorkitem represents a pending approval work item associated with a ProcessInstanceId. ActorId, OriginalActorId, and CreatedDate identify its current and original actors and when the work item was created.","fields":[{"name":"ActorId","type":"Lookup","description":"The user or queue this workitem is assigned to"},{"name":"ProcessInstanceId","type":"Lookup","description":"The approval process instance this workitem belongs to"},{"name":"OriginalActorId","type":"Lookup","description":"The originally assigned actor before any delegation or reassignment"},{"name":"CreatedDate","type":"DateTime","description":"When this workitem was assigned to the approver"}],"relationships":[{"target":"ProcessInstance","type":"child","description":"Each workitem is part of one approval process instance"}]}
    ]
  },

  "orchestrator": {
    "objects": [
      {"name":"FulfillmentOrder","type":"standard","domain":"orchestrator","description":"FulfillmentOrder groups fulfillment order line items and can represent a technical order placed on a fulfillment subsystem. FulfillmentOrderNumber identifies the record, while Status, AccountId, OrderId, FulfilledToName, and Type capture its state, source order, account, fulfillment recipient, and classification.","fields":[{"name":"FulfillmentOrderNumber","type":"Text","description":"System-generated unique number for this fulfillment order"},{"name":"Status","type":"Picklist","description":"Fulfillment state such as allocated, fulfilled, or cancelled"},{"name":"AccountId","type":"Lookup","description":"The customer account this fulfillment is for"},{"name":"OrderId","type":"Lookup","description":"The source order being fulfilled"},{"name":"FulfilledToName","type":"Text","description":"Name of the recipient for physical deliveries"},{"name":"Type","type":"Picklist","description":"Whether this is a physical shipment, digital provisioning, or service activation"}],"relationships":[{"target":"FulfillmentOrderLineItem","type":"parent","description":"A fulfillment order contains line items specifying what is being fulfilled"},{"target":"Order","type":"child","description":"Each fulfillment order originates from a customer order"}]},
      {"name":"FulfillmentOrderLineItem","type":"standard","domain":"orchestrator","description":"FulfillmentOrderLineItem represents a technical product created by the order decomposition process. Product2Id identifies the technical product, OrderItemId links it to the source order item, and Quantity, TotalPrice, and Type describe the fulfillment quantity, amount, and line classification.","fields":[{"name":"Product2Id","type":"Lookup","description":"The product being fulfilled"},{"name":"Quantity","type":"Number","description":"Number of units included in this fulfillment"},{"name":"OrderItemId","type":"Lookup","description":"The source order item this line fulfills"},{"name":"TotalPrice","type":"Currency","description":"Financial value of the fulfilled quantity"},{"name":"Type","type":"Picklist","description":"Fulfillment type such as ship, deliver, or transfer"}],"relationships":[{"target":"FulfillmentOrder","type":"child","description":"Each line item belongs to one fulfillment order"},{"target":"OrderItem","type":"child","description":"Maps back to the order item being fulfilled"}]},
      {"name":"OrderDeliveryGroup","type":"standard","domain":"orchestrator","description":"OrderDeliveryGroup associates an order with a set of delivery details. OrderId identifies the order, while DeliverToName, DeliverToStreet, DeliverToCity, and DeliveryMethod capture the recipient, destination, and delivery method.","fields":[{"name":"OrderId","type":"Lookup","description":"The order this delivery group belongs to"},{"name":"DeliverToName","type":"Text","description":"Recipient name for this delivery group"},{"name":"DeliverToStreet","type":"Text","description":"Delivery street address"},{"name":"DeliverToCity","type":"Text","description":"Delivery city"},{"name":"DeliveryMethod","type":"Picklist","description":"How items in this group are delivered, such as standard shipping or digital"}],"relationships":[{"target":"Order","type":"child","description":"Each delivery group is part of one order"},{"target":"FulfillmentOrder","type":"parent","description":"Fulfillment orders are created per delivery group"}]},
      {"name":"OrderAction","type":"standard","domain":"orchestrator","description":"OrderAction represents an action associated with an order and provides a reference for related asset lifecycle activity. Type identifies the action, OrderId links it to the order, EffectiveDate specifies when it applies, and StatusCode records its processing status.","fields":[{"name":"Type","type":"Picklist","description":"The kind of action: new sale, amendment, renewal, suspension, or cancellation"},{"name":"OrderId","type":"Lookup","description":"The order this action was performed on"},{"name":"EffectiveDate","type":"Date","description":"Date when this action takes effect"},{"name":"StatusCode","type":"Picklist","description":"Processing status of this action"}],"relationships":[{"target":"Order","type":"child","description":"Each action references the order it modifies"},{"target":"OrderItemAction","type":"parent","description":"An order action contains item-level actions detailing what changed"}]},
      {"name":"AssetAction","type":"standard","domain":"orchestrator","description":"AssetAction records a lifecycle change to an Asset, including initial sale, amendment, renewal, and cancellation. AssetId identifies the affected asset, while Type, Amount, ActionDate, and Quantity record the action category, financial impact, effective date, and quantity change.","fields":[{"name":"AssetId","type":"Lookup","description":"The customer asset affected by this action"},{"name":"Type","type":"Picklist","description":"The type of change: create, upgrade, downgrade, renew, or cancel"},{"name":"Amount","type":"Currency","description":"Financial impact of this asset change"},{"name":"ActionDate","type":"Date","description":"Date when this asset change takes effect"},{"name":"Quantity","type":"Number","description":"Change in quantity, positive for additions and negative for removals"}],"relationships":[{"target":"Asset","type":"child","description":"Each action references the asset being changed"},{"target":"AssetStatePeriod","type":"parent","description":"Asset actions generate state periods reflecting the new asset state"}]},
      {"name":"AssetStatePeriod","type":"standard","domain":"orchestrator","description":"AssetStatePeriod represents a period during which an asset maintains a consistent quantity, amount, and monthly recurring revenue. AssetId identifies the asset, StartDate and EndDate bound the period, and Amount, Mrr, and Quantity capture its financial and quantity state.","fields":[{"name":"AssetId","type":"Lookup","description":"The asset this state period describes"},{"name":"StartDate","type":"Date","description":"Beginning of this state period"},{"name":"EndDate","type":"Date","description":"End of this state period"},{"name":"Amount","type":"Currency","description":"Total financial value during this period"},{"name":"Mrr","type":"Currency","description":"Monthly recurring revenue during this period"},{"name":"Quantity","type":"Number","description":"Asset quantity during this state period"}],"relationships":[{"target":"Asset","type":"child","description":"Each state period belongs to one asset"},{"target":"AssetAction","type":"child","description":"State periods are created or modified by asset actions"}]}
    ]
  },

  "usage": {
    "objects": [
      {"name":"UsageSummary","type":"standard","domain":"usage","description":"UsageSummary stores aggregated consumption for a usage entitlement over the period identified by SummaryStartDate and SummaryEndDate. TotalQuantity and Status track the summarized amount and processing state, while OrderItemId and AccountId associate the summary with the relevant transaction and customer account.","fields":[{"name":"SummaryStartDate","type":"Date","description":"Beginning of the measurement period"},{"name":"SummaryEndDate","type":"Date","description":"End of the measurement period"},{"name":"TotalQuantity","type":"Number","description":"Total consumption recorded during this period"},{"name":"Status","type":"Picklist","description":"Processing state such as new, rated, billed, or invoiced"},{"name":"OrderItemId","type":"Lookup","description":"The subscription or order line item this usage relates to"},{"name":"AccountId","type":"Lookup","description":"The customer account this usage belongs to"}],"relationships":[{"target":"OrderItem","type":"child","description":"Usage summaries are tied to a specific order item or subscription"},{"target":"BillingSchedule","type":"lookup","description":"Rated usage feeds into billing schedules for invoicing"}]},
      {"name":"UsageQuantity","type":"standard","domain":"usage","description":"UsageQuantity captures a dated quantity associated with a UsageSummary through UsageSummaryId. UsageDate, Quantity, and UsageType describe the usage entry, while ExternalReference retains its external reference.","fields":[{"name":"UsageDate","type":"DateTime","description":"Timestamp when this usage event occurred"},{"name":"Quantity","type":"Number","description":"The measured amount of consumption"},{"name":"UsageType","type":"Picklist","description":"Category of consumption such as storage, compute, or transactions"},{"name":"UsageSummaryId","type":"Lookup","description":"The summary this individual measurement rolls up to"},{"name":"ExternalReference","type":"Text","description":"Identifier linking this record to the source metering system"}],"relationships":[{"target":"UsageSummary","type":"child","description":"Individual usage records roll up to a usage summary"}]}
    ]
  },

  "billing": {
    "objects": [
      {"name":"BillingSchedule","type":"standard","domain":"billing","description":"BillingSchedule stores the order item information used in invoicing and represents when and how that item is billed. BillingScheduleNumber identifies the schedule, while OrderItemId, TotalAmount, Status, BillingFrequency, and NextBillingDate track its source, amount, processing state, cadence, and upcoming billing date.","fields":[{"name":"BillingScheduleNumber","type":"Text","description":"System-generated identifier for this billing schedule"},{"name":"OrderItemId","type":"Lookup","description":"The order line item this schedule bills for"},{"name":"TotalAmount","type":"Currency","description":"Total amount to be billed across all periods in this schedule"},{"name":"Status","type":"Picklist","description":"Current state such as active, suspended, or completed"},{"name":"BillingFrequency","type":"Picklist","description":"How often invoices are generated: monthly, quarterly, or annually"},{"name":"NextBillingDate","type":"Date","description":"Date when the next invoice will be generated"}],"relationships":[{"target":"OrderItem","type":"child","description":"Each billing schedule is created from an order item"},{"target":"Invoice","type":"parent","description":"Billing schedules generate invoice records on each billing cycle"},{"target":"BillingScheduleGroup","type":"child","description":"Schedules can be grouped together for consolidated billing"}]},
      {"name":"BillingScheduleGroup","type":"standard","domain":"billing","description":"BillingScheduleGroup consolidates related BillingSchedule records, including schedules created for an asset's new orders and amendment orders. Name and AccountId identify the group and customer, while BillingFrequency and NextBillingDate support recurring invoice processing.","fields":[{"name":"Name","type":"Text","description":"Display name for this billing group"},{"name":"AccountId","type":"Lookup","description":"The customer account whose schedules are grouped"},{"name":"BillingFrequency","type":"Picklist","description":"Common billing frequency for all schedules in this group"},{"name":"NextBillingDate","type":"Date","description":"Next date when a consolidated invoice will be generated"}],"relationships":[{"target":"BillingSchedule","type":"parent","description":"A group contains one or more billing schedules"},{"target":"Account","type":"child","description":"Each group is associated with one customer account"}]},
      {"name":"Invoice","type":"standard","domain":"billing","description":"Invoice represents amounts billed to an account and tracks the transaction through draft, posting, settlement, voiding, or cancellation processes. InvoiceNumber, AccountId, TotalAmount, Balance, Status, InvoiceDate, and DueDate identify the document and summarize its financial and payment status.","fields":[{"name":"InvoiceNumber","type":"Text","description":"Unique number identifying this invoice"},{"name":"AccountId","type":"Lookup","description":"The customer account being billed"},{"name":"TotalAmount","type":"Currency","description":"Grand total of all line items on this invoice"},{"name":"Balance","type":"Currency","description":"Remaining unpaid amount after any payments applied"},{"name":"Status","type":"Picklist","description":"Current state such as draft, posted, paid, or cancelled"},{"name":"InvoiceDate","type":"Date","description":"Date the invoice was issued"},{"name":"DueDate","type":"Date","description":"Date by which payment is expected"}],"relationships":[{"target":"InvoiceLine","type":"parent","description":"An invoice contains one or more line items"},{"target":"Payment","type":"parent","description":"Payments can be applied to reduce the invoice balance"},{"target":"CreditMemo","type":"lookup","description":"Credit memos can be applied to offset invoice charges"},{"target":"FinanceTransaction","type":"parent","description":"Invoice posting creates finance transaction records"}]},
      {"name":"InvoiceLine","type":"standard","domain":"billing","description":"InvoiceLine represents the amount a buyer must pay for a product, service, or fee and is created from billable transaction amounts. InvoiceId links the line to its invoice, while Name, Quantity, UnitPrice, LineAmount, TaxAmount, and Product2Id describe the billed item and its charge.","fields":[{"name":"InvoiceId","type":"Lookup","description":"The invoice this line item belongs to"},{"name":"Name","type":"Text","description":"Description of the charge on this line"},{"name":"Quantity","type":"Number","description":"Number of units being billed"},{"name":"UnitPrice","type":"Currency","description":"Price per unit for this line item"},{"name":"LineAmount","type":"Currency","description":"Total charge for this line before tax"},{"name":"TaxAmount","type":"Currency","description":"Tax calculated for this line item"},{"name":"Product2Id","type":"Lookup","description":"The product this charge relates to"}],"relationships":[{"target":"Invoice","type":"child","description":"Each line item belongs to one invoice"},{"target":"Product2","type":"lookup","description":"References the product being billed"}]},
      {"name":"CreditMemo","type":"standard","domain":"billing","description":"CreditMemo represents a document used to reduce the amount a buyer owes, including adjustments for billing errors, returns, discounts, cancellations, or overpayments. CreditMemoNumber, AccountId, TotalAmount, Balance, Status, and CreditDate identify the credit and track its available and applied amounts.","fields":[{"name":"CreditMemoNumber","type":"Text","description":"Unique number identifying this credit memo"},{"name":"AccountId","type":"Lookup","description":"The customer account receiving the credit"},{"name":"TotalAmount","type":"Currency","description":"Total credit amount across all line items"},{"name":"Balance","type":"Currency","description":"Remaining credit not yet applied to invoices"},{"name":"Status","type":"Picklist","description":"Current state such as draft, posted, or applied"},{"name":"CreditDate","type":"Date","description":"Date this credit memo was issued"}],"relationships":[{"target":"CreditMemoLine","type":"parent","description":"A credit memo contains one or more line items detailing the credits"},{"target":"Invoice","type":"lookup","description":"Credits can be applied to specific invoices"},{"target":"FinanceTransaction","type":"parent","description":"Credit memo posting creates finance transaction records"}]},
      {"name":"CreditMemoLine","type":"standard","domain":"billing","description":"CreditMemoLine records an individual credited product, service, or tax amount within a CreditMemo. CreditMemoId links it to the parent document, while Name, Quantity, LineAmount, TaxAmount, and Product2Id describe the credited item.","fields":[{"name":"CreditMemoId","type":"Lookup","description":"The credit memo this line belongs to"},{"name":"Name","type":"Text","description":"Description of the credit being issued"},{"name":"Quantity","type":"Number","description":"Number of units being credited"},{"name":"LineAmount","type":"Currency","description":"Total credit amount for this line"},{"name":"TaxAmount","type":"Currency","description":"Tax credit associated with this line"},{"name":"Product2Id","type":"Lookup","description":"The product being credited"}],"relationships":[{"target":"CreditMemo","type":"child","description":"Each line belongs to one credit memo"},{"target":"InvoiceLine","type":"lookup","description":"Credits can reference the original invoice line being adjusted"}]},
      {"name":"DebitMemo","type":"standard","domain":"billing","description":"DebitMemo represents additional charges issued to a buyer for scenarios such as underbilling, late fees, or cancellation charges. DebitMemoNumber, AccountId, TotalAmount, Balance, Status, and DebitDate identify the document and track the added obligation.","fields":[{"name":"DebitMemoNumber","type":"Text","description":"Unique number identifying this debit memo"},{"name":"AccountId","type":"Lookup","description":"The customer account being charged"},{"name":"TotalAmount","type":"Currency","description":"Total additional charge across all line items"},{"name":"Balance","type":"Currency","description":"Remaining unpaid amount on this debit memo"},{"name":"Status","type":"Picklist","description":"Current state such as draft, posted, or paid"},{"name":"DebitDate","type":"Date","description":"Date this debit memo was issued"}],"relationships":[{"target":"DebitMemoLine","type":"parent","description":"A debit memo contains one or more charge line items"},{"target":"FinanceTransaction","type":"parent","description":"Debit memo posting creates finance transaction records"}]},
      {"name":"DebitMemoLine","type":"standard","domain":"billing","description":"DebitMemoLine represents the additional amount a buyer must pay for a product, service, or related tax. DebitMemoId associates the line with its DebitMemo, while Name, Quantity, LineAmount, TaxAmount, and Product2Id describe the additional charge.","fields":[{"name":"DebitMemoId","type":"Lookup","description":"The debit memo this line belongs to"},{"name":"Name","type":"Text","description":"Description of the additional charge"},{"name":"Quantity","type":"Number","description":"Number of units being charged"},{"name":"LineAmount","type":"Currency","description":"Total charge for this line before tax"},{"name":"TaxAmount","type":"Currency","description":"Tax calculated for this additional charge"},{"name":"Product2Id","type":"Lookup","description":"The product this charge relates to"}],"relationships":[{"target":"DebitMemo","type":"child","description":"Each line belongs to one debit memo"}]},
      {"name":"BillingTreatment","type":"standard","domain":"billing","description":"BillingTreatment defines how Revenue Cloud bills an order item and is selected through its parent BillingPolicy. Name, BillingCycleType, BillingFrequency, ProrationType, and BillingPolicyId capture the treatment's identity, billing cadence, proration behavior, and policy relationship.","fields":[{"name":"Name","type":"Text","description":"Descriptive label for this billing treatment"},{"name":"BillingCycleType","type":"Picklist","description":"Whether charges are billed in advance, in arrears, or on consumption"},{"name":"BillingFrequency","type":"Picklist","description":"How often charges are billed: monthly, quarterly, or annually"},{"name":"ProrationType","type":"Picklist","description":"How mid-cycle starts and cancellations are prorated"},{"name":"BillingPolicyId","type":"Lookup","description":"The billing policy governing this treatment's behavior"}],"relationships":[{"target":"BillingTreatmentItem","type":"parent","description":"A treatment contains items specifying product-level billing rules"},{"target":"BillingPolicy","type":"child","description":"Each treatment follows rules from a billing policy"}]},
      {"name":"BillingTreatmentItem","type":"standard","domain":"billing","description":"BillingTreatmentItem defines how an order item's total amount is distributed into Billing Schedules during its lifecycle. BillingTreatmentId identifies the treatment, while Product2Id, ProductFamily, and IsActive associate and control the treatment item for applicable products.","fields":[{"name":"BillingTreatmentId","type":"Lookup","description":"The billing treatment this item belongs to"},{"name":"Product2Id","type":"Lookup","description":"The specific product this billing rule applies to"},{"name":"ProductFamily","type":"Picklist","description":"The product family this rule applies to, if not product-specific"},{"name":"IsActive","type":"Boolean","description":"Whether this treatment item is currently in effect"}],"relationships":[{"target":"BillingTreatment","type":"child","description":"Each item belongs to one billing treatment"},{"target":"Product2","type":"lookup","description":"References the product with specific billing rules"}]},
      {"name":"BillingPolicy","type":"standard","domain":"billing","description":"BillingPolicy groups Billing Treatments that define the rules for invoicing order items and is related to products. Name, Description, DefaultPaymentTerms, and Status identify the policy, document its purpose, provide its default terms, and control whether it is available for billing.","fields":[{"name":"Name","type":"Text","description":"Descriptive name for this billing policy"},{"name":"Description","type":"TextArea","description":"Explanation of when and where this policy applies"},{"name":"DefaultPaymentTerms","type":"Number","description":"Default number of days from invoice date to due date"},{"name":"Status","type":"Picklist","description":"Whether this policy is active or inactive"}],"relationships":[{"target":"BillingTreatment","type":"parent","description":"A policy governs one or more billing treatments"}]},
      {"name":"Payment","type":"standard","domain":"billing","description":"Payment records an amount collected from an account and can be applied to an Invoice or Invoice Line according to the configured application level. PaymentNumber, Amount, Status, PaymentDate, AccountId, and PaymentMethodId identify the transaction, its customer, and the method used.","fields":[{"name":"PaymentNumber","type":"Text","description":"Unique identifier for this payment"},{"name":"Amount","type":"Currency","description":"Total amount collected in this payment"},{"name":"Status","type":"Picklist","description":"Processing state such as draft, processed, or applied"},{"name":"PaymentDate","type":"Date","description":"Date the payment was received or processed"},{"name":"AccountId","type":"Lookup","description":"The customer account making the payment"},{"name":"PaymentMethodId","type":"Lookup","description":"The payment method used for this transaction"}],"relationships":[{"target":"Invoice","type":"child","description":"Payments are applied to invoices to reduce the balance"},{"target":"PaymentMethod","type":"child","description":"Each payment uses a stored payment method"},{"target":"FinanceTransaction","type":"parent","description":"Payment application creates finance transaction records"}]},
      {"name":"PaymentMethod","type":"standard","domain":"billing","description":"PaymentMethod represents payment details associated with an account for one-time or recurring payment processing. Name, PaymentMethodType, AccountId, Status, and ExpirationDate identify the method, its owner, availability, and validity.","fields":[{"name":"Name","type":"Text","description":"Display label for this payment method, such as card ending in 4242"},{"name":"PaymentMethodType","type":"Picklist","description":"Type of instrument: credit card, bank transfer, or digital wallet"},{"name":"AccountId","type":"Lookup","description":"The customer account this method belongs to"},{"name":"Status","type":"Picklist","description":"Whether this method is active, expired, or cancelled"},{"name":"ExpirationDate","type":"Date","description":"When this payment method expires, if applicable"}],"relationships":[{"target":"Payment","type":"parent","description":"A payment method can be used for multiple payments"},{"target":"Account","type":"child","description":"Each payment method belongs to a customer account"}]},
      {"name":"FinanceTransaction","type":"standard","domain":"billing","description":"FinanceTransaction records a financial transaction associated with an account and a referenced business entity. TransactionDate, Amount, TransactionType, ReferenceEntityId, AccountId, and FinanceSystemTransactionNumber support classification, traceability, and external finance-system reconciliation.","fields":[{"name":"TransactionDate","type":"Date","description":"Date this financial transaction was recorded"},{"name":"Amount","type":"Currency","description":"Monetary value of this transaction entry"},{"name":"TransactionType","type":"Picklist","description":"Category such as charge, payment, credit, refund, or adjustment"},{"name":"ReferenceEntityId","type":"Lookup","description":"The source document that created this transaction, such as an invoice or payment"},{"name":"AccountId","type":"Lookup","description":"The customer account this transaction relates to"},{"name":"FinanceSystemTransactionNumber","type":"Text","description":"External reference for reconciliation with the general ledger"}],"relationships":[{"target":"FinanceBalanceSnapshot","type":"parent","description":"Transactions contribute to periodic balance snapshots"},{"target":"Invoice","type":"child","description":"Invoice posting generates finance transactions"},{"target":"Payment","type":"child","description":"Payment processing generates finance transactions"}]},
      {"name":"FinanceBalanceSnapshot","type":"standard","domain":"billing","description":"FinanceBalanceSnapshot captures an account's financial position on a specified date. AccountId and SnapshotDate identify the snapshot, while TotalInvoiced, TotalPayments, OutstandingBalance, and CreditBalance summarize billed, paid, due, and available credit amounts.","fields":[{"name":"AccountId","type":"Lookup","description":"The customer account this snapshot covers"},{"name":"SnapshotDate","type":"Date","description":"The date this balance snapshot was captured"},{"name":"TotalInvoiced","type":"Currency","description":"Cumulative amount invoiced through the snapshot date"},{"name":"TotalPayments","type":"Currency","description":"Cumulative payments received through the snapshot date"},{"name":"OutstandingBalance","type":"Currency","description":"Amount currently owed by the customer"},{"name":"CreditBalance","type":"Currency","description":"Available credit from unapplied credit memos"}],"relationships":[{"target":"Account","type":"child","description":"Each snapshot belongs to a customer account"},{"target":"FinanceTransaction","type":"child","description":"Snapshots are calculated from accumulated finance transactions"}]},
      {"name":"TaxTreatment","type":"standard","domain":"billing","description":"TaxTreatment defines how Revenue Cloud or an external Tax Engine calculates taxes and identifies the engine to use. Name, TaxEngineId, TaxType, TaxPolicyId, and IsActive capture the treatment's configuration, policy relationship, and availability.","fields":[{"name":"Name","type":"Text","description":"Descriptive label for this tax treatment"},{"name":"TaxEngineId","type":"Lookup","description":"The tax calculation engine used by this treatment"},{"name":"TaxType","type":"Picklist","description":"Category of tax such as sales, VAT, or GST"},{"name":"TaxPolicyId","type":"Lookup","description":"The tax policy this treatment follows"},{"name":"IsActive","type":"Boolean","description":"Whether this tax treatment is currently applied"}],"relationships":[{"target":"InvoiceLine","type":"lookup","description":"Tax treatments determine how tax is calculated on invoice lines"},{"target":"Product2","type":"lookup","description":"Tax treatments can be assigned to specific products"}]},
      {"name":"LegalEntity","type":"standard","domain":"billing","description":"LegalEntity represents an organizational structure used to govern billing, tax, accounting periods, and financial treatment. Name, CompanyNumber, Status, Country, and CurrencyIsoCode identify the entity, its jurisdiction, operating state, and functional currency.","fields":[{"name":"Name","type":"Text","description":"Official legal name of this business entity"},{"name":"CompanyNumber","type":"Text","description":"Government registration number for this entity"},{"name":"Status","type":"Picklist","description":"Whether this entity is active or inactive"},{"name":"Country","type":"Text","description":"Country where this legal entity is registered"},{"name":"CurrencyIsoCode","type":"Text","description":"Default currency for this entity's financial transactions"}],"relationships":[{"target":"Invoice","type":"parent","description":"A legal entity issues invoices on behalf of the organization"},{"target":"FinanceTransaction","type":"parent","description":"Finance transactions are attributed to a legal entity for reporting"}]}
    ]
  },

  "agentforce": {
    "objects": [
      {"name":"AgentAction","type":"standard","domain":"agentforce","description":"AgentAction represents a configured action that an agent can invoke for an authorized Revenue Cloud operation. Name and Description identify the action, ActionType classifies it, TargetObject identifies the associated object, and IsActive indicates whether the action is available for use.","fields":[{"name":"Name","type":"Text","description":"Display name describing what this agent action does"},{"name":"ActionType","type":"Picklist","description":"Category of action such as query, create, update, or recommend"},{"name":"TargetObject","type":"Text","description":"The object this action operates on, such as quote or invoice"},{"name":"IsActive","type":"Boolean","description":"Whether this action is available for agents to invoke"},{"name":"Description","type":"TextArea","description":"Natural language explanation of what this action does and when to use it"}],"relationships":[{"target":"Quote","type":"lookup","description":"Agent actions can create or modify quotes"},{"target":"Order","type":"lookup","description":"Agent actions can interact with order records"}]}
    ]
  },

  "promotions": {
    "objects": [
      {"name":"Promotion","type":"standard","domain":"promotions","description":"The Promotion object represents a promotional offer and stores its Name, Description, effective StartDate and EndDate, and Status. DiscountType and DiscountValue define the adjustment offered when the promotion is eligible.","fields":[{"name":"Name","type":"Text","description":"Marketing name for this promotion"},{"name":"Description","type":"TextArea","description":"Details about the offer and its intended audience"},{"name":"StartDate","type":"Date","description":"Date when this promotion becomes available"},{"name":"EndDate","type":"Date","description":"Date when this promotion expires"},{"name":"Status","type":"Picklist","description":"Current state such as planned, active, or expired"},{"name":"DiscountType","type":"Picklist","description":"Whether the offer is a percentage discount, fixed amount, or free trial"},{"name":"DiscountValue","type":"Number","description":"The discount amount or percentage applied by this promotion"}],"relationships":[{"target":"PromotionTarget","type":"parent","description":"A promotion specifies which products or categories are eligible"},{"target":"PromotionQualifier","type":"parent","description":"Qualifiers define the conditions a transaction must meet"}]},
      {"name":"PromotionTarget","type":"standard","domain":"promotions","description":"The PromotionTarget object associates a Promotion with the item identified by TargetType and TargetId. AdjustmentPercent records the percentage adjustment associated with that promotion target.","fields":[{"name":"PromotionId","type":"Lookup","description":"The promotion this target belongs to"},{"name":"TargetType","type":"Picklist","description":"Whether the target is a specific product, category, or product family"},{"name":"TargetId","type":"Lookup","description":"Reference to the specific product or category"},{"name":"AdjustmentPercent","type":"Percent","description":"Override discount percentage for this specific target, if different from the promotion default"}],"relationships":[{"target":"Promotion","type":"child","description":"Each target belongs to one promotion"},{"target":"Product2","type":"lookup","description":"Targets can reference specific products"}]},
      {"name":"PromotionQualifier","type":"standard","domain":"promotions","description":"The PromotionQualifier object stores an eligibility condition for a Promotion. QualifierType, QualifierValue, and Operator define the value and comparison used by the condition.","fields":[{"name":"PromotionId","type":"Lookup","description":"The promotion this qualifier belongs to"},{"name":"QualifierType","type":"Picklist","description":"Type of condition such as minimum amount, customer segment, or product requirement"},{"name":"QualifierValue","type":"Text","description":"The threshold or value that must be met"},{"name":"Operator","type":"Picklist","description":"Comparison operator such as equals, greater than, or contains"}],"relationships":[{"target":"Promotion","type":"child","description":"Each qualifier belongs to one promotion"}]},
      {"name":"PromotionMarketSegment","type":"standard","domain":"promotions","description":"The PromotionMarketSegment object associates a Promotion with a named market segment. SegmentCriteria stores the segment criteria, while IsActive indicates whether the association is active.","fields":[{"name":"PromotionId","type":"Lookup","description":"The promotion this segment assignment belongs to"},{"name":"SegmentName","type":"Text","description":"Name of the market segment, such as enterprise or small business"},{"name":"SegmentCriteria","type":"TextArea","description":"Description of the criteria that define membership in this segment"},{"name":"IsActive","type":"Boolean","description":"Whether this segment is currently eligible for the promotion"}],"relationships":[{"target":"Promotion","type":"child","description":"Each segment assignment belongs to one promotion"}]}
    ]
  },

  "intelligence": {
    "objects": [
      {"name":"RevenueAnalyticsDataset","type":"standard","domain":"intelligence","description":"RevenueAnalyticsDataset identifies an analytics dataset by Name and DatasetType and records its LastRefreshDate, RefreshFrequency, and Status. The supplied documentation doesn’t describe this object’s behavior or lifecycle beyond the listed fields.","fields":[{"name":"Name","type":"Text","description":"Identifying name for this analytics dataset"},{"name":"DatasetType","type":"Picklist","description":"Category of data such as orders, billing, usage, or combined"},{"name":"LastRefreshDate","type":"DateTime","description":"When this dataset was last refreshed from source data"},{"name":"RefreshFrequency","type":"Picklist","description":"How often the dataset is refreshed: hourly, daily, or weekly"},{"name":"Status","type":"Picklist","description":"Current state of the dataset such as active, refreshing, or error"}],"relationships":[{"target":"Order","type":"lookup","description":"Datasets aggregate order data for revenue reporting"},{"target":"Invoice","type":"lookup","description":"Datasets include billing data for financial analysis"}]}
    ]
  },

  "setup": {
    "objects": [
      {"name":"RevenueCloudSettings","type":"standard","domain":"setup","description":"RevenueCloudSettings represents organization-level Revenue Cloud configuration through IsBillingEnabled, IsUsageBasedPricingEnabled, DefaultPaymentTerms, DefaultBillingFrequency, and TaxEngineId. These values identify enabled billing and usage capabilities and the defaults or tax engine used for related processing.","fields":[{"name":"IsBillingEnabled","type":"Boolean","description":"Master switch for enabling the billing engine"},{"name":"IsUsageBasedPricingEnabled","type":"Boolean","description":"Whether consumption-based pricing features are active"},{"name":"DefaultPaymentTerms","type":"Number","description":"Organization-wide default payment terms in days"},{"name":"DefaultBillingFrequency","type":"Picklist","description":"Default cadence for new billing schedules"},{"name":"TaxEngineId","type":"Lookup","description":"The default tax calculation engine for all transactions"}],"relationships":[{"target":"BillingPolicy","type":"lookup","description":"Settings reference the default billing policy"},{"target":"LegalEntity","type":"lookup","description":"Settings reference the default legal entity for transactions"}]},
      {"name":"RevenuePermissionSet","type":"standard","domain":"setup","description":"RevenuePermissionSet represents a Revenue Cloud permission set identified by Name and Description. License and IsActive indicate its associated license and whether the permission set is active.","fields":[{"name":"Name","type":"Text","description":"Name of the permission set, such as Revenue Cloud Admin or Billing User"},{"name":"Description","type":"TextArea","description":"Explanation of the access level and intended audience"},{"name":"License","type":"Text","description":"The Salesforce license type required to use this permission set"},{"name":"IsActive","type":"Boolean","description":"Whether this permission set is currently assignable to users"}],"relationships":[{"target":"RevenueCloudSettings","type":"lookup","description":"Permission sets control who can modify Revenue Cloud settings"}]},
      {"name":"DataTransferObject","type":"standard","domain":"setup","description":"DataTransferObject represents a configured transfer from SourceSystem to TargetObject and is identified by Name. Status and LastRunDate record the transfer's current state and most recent run date.","fields":[{"name":"Name","type":"Text","description":"Identifying name for this data transfer configuration"},{"name":"SourceSystem","type":"Text","description":"Name of the system data is being imported from"},{"name":"TargetObject","type":"Text","description":"The Revenue Cloud object data is being imported into"},{"name":"Status","type":"Picklist","description":"Current state of the transfer such as configured, running, or completed"},{"name":"LastRunDate","type":"DateTime","description":"When this transfer was last executed"}],"relationships":[{"target":"Order","type":"lookup","description":"Data transfers can import order data from external systems"},{"target":"Invoice","type":"lookup","description":"Data transfers can import historical invoice data"}]}
    ]
  }

};
